4		"strings"
5		"testing"
6		"time"
7	
8		tea "charm.land/bubbletea/v2"
9		"github.com/charmbracelet/x/ansi"
10	
11		"github.com/anthnel/devdesk/internal/config"
12		"github.com/anthnel/devdesk/internal/jobs"
13		"github.com/anthnel/devdesk/internal/netcheck"
14		"github.com/anthnel/devdesk/internal/nettrace"
15		"github.com/anthnel/devdesk/internal/ui/components"
16		"github.com/anthnel/devdesk/internal/ui/testutil"
17	)
18	
19	// DEVDESK-328 step 5: the Path tab wired into the netdiag Model. No test runs a
20	// Cmd that would start the producer: the run is driven by feeding messages.
21	
22	// onPathTab returns a laid-out model standing on the Path tab, with a fake
23	// engine so that enter never touches a socket or a resolver.
24	func onPathTab(t *testing.T) *Model {
25		t.Helper()
26		m := newTestModel(t)
27		if m.pathModel == nil {
28			t.Fatal("New() built no pathModel")
29		}
30		m.pathModel.engine = (&fakeEngine{}).engine()
31		return feed(t, m, testutil.Keys("tab", "tab", "tab", "tab")...)
32	}
33	
34	// tracing returns a model on the Path tab with a trace launched over host.
35	func tracing(t *testing.T, host string) *Model {
36		t.Helper()
37		m := onPathTab(t)
38		m = feed(t, m, testutil.Type(host)...)
39		return feed(t, m, testutil.Key("enter"))
40	}
41	
42	func TestPathIsTheFifthTab(t *testing.T) {
43		if tabPath != 4 {
44			t.Errorf("tabPath = %d, want 4 (the fifth tab, after Forward)", tabPath)
45		}
46		if tabCount != 5 {
47			t.Errorf("tabCount = %d, want 5", tabCount)
48		}
49	}
50	
51	func TestPathIsReachedByTabAloneAndCyclesBothWays(t *testing.T) {
52		m := newTestModel(t)
53		for _, want := range []int{tabPorts, tabInterfaces, tabForward, tabPath, tabDiagnostics} {
54			m = feed(t, m, testutil.Key("tab"))
55			if m.activeTab != want {
56				t.Fatalf("tab: activeTab = %d, want %d", m.activeTab, want)
57			}
58		}
59		for _, want := range []int{tabPath, tabForward, tabInterfaces, tabPorts, tabDiagnostics} {
60			m = feed(t, m, testutil.Key("shift+tab"))
61			if m.activeTab != want {
62				t.Fatalf("shift+tab: activeTab = %d, want %d", m.activeTab, want)
63			}
64		}
65	}
66	
67	// tab is never a field key on Path, so it leaves the tab even while the field
68	// has the keyboard.
69	func TestTabLeavesPathWhileTheFieldIsEditing(t *testing.T) {
70		m := onPathTab(t)
71		if !m.InEditMode() {
72			t.Fatal("precondition: the field should be editing")
73		}
74		m = feed(t, m, testutil.Key("tab"))
75		if m.activeTab != tabDiagnostics {
76			t.Errorf("activeTab = %d, want %d", m.activeTab, tabDiagnostics)
77		}
78	}
79	
80	func TestPathRenderIsTheTableInEveryState(t *testing.T) {
81		m := onPathTab(t)
82		states := map[string]*Model{"editing": m}
83	
84		run := feed(t, onPathTab(t), testutil.Type("example.com")...)
85		run = feed(t, run, testutil.Key("enter"))
86		states["running"] = run
87	
88		done := feed(t, run, pathDoneMsg{gen: run.pathModel.gen, result: nettrace.Result{}})
89		states["done"] = done
90	
91		for name, mm := range states {
92			if got, want := mm.Render(), mm.pathModel.view(); got != want {
93				t.Errorf("%s: Render() is not the table view (Rule 139)", name)
94			}
95		}
96	}
97	
98	func TestPathFooterHeightIsFiveInEveryState(t *testing.T) {
99		m := onPathTab(t)
100		if got := m.GetFooterHeight(); got != 5 {
101			t.Errorf("editing: GetFooterHeight() = %d, want 5", got)
102		}
103		m = feed(t, m, testutil.Type("example.com")...)
104		m = feed(t, m, testutil.Key("enter"))
105		if got := m.GetFooterHeight(); got != 5 {
106			t.Errorf("running: GetFooterHeight() = %d, want 5", got)
107		}
108		m = feed(t, m, pathDoneMsg{gen: m.pathModel.gen, result: nettrace.Result{}})
109		if got := m.GetFooterHeight(); got != 5 {
110			t.Errorf("done: GetFooterHeight() = %d, want 5", got)
111		}
112	}
113	
114	func TestPathFooterHoldsTheBarAndTheTabLabel(t *testing.T) {
115		plain := ansi.Strip(onPathTab(t).RenderFooter(120))
116		for _, want := range []string{"Target ›", "Path", "Diagnostics", "Forward"} {
117			if !strings.Contains(plain, want) {
118				t.Errorf("RenderFooter lacks %q:\n%s", want, plain)
119			}
120		}
121		if got := strings.Count(plain, "\n") + 1; got != 5 {
122			t.Errorf("RenderFooter is %d lines, want 5 (bar 2, tabs, blank, info)", got)
123		}
124	}
