1	package netdiag
2	
3	import (
4		"errors"
5		"net"
6		"net/netip"
7		"reflect"
8		"strings"
9		"testing"
10	
11		"github.com/charmbracelet/x/ansi"
12	
13		"github.com/anthnel/devdesk/internal/netcheck"
14		"github.com/anthnel/devdesk/internal/nettrace"
15		"github.com/anthnel/devdesk/internal/ui/components"
16		"github.com/anthnel/devdesk/internal/ui/testutil"
17	)
18	
19	// DEVDESK-329 step 3: the table shows source, interface, gateway, then hops.
20	
21	// pmColumn returns one cell per table row, read through the column functions.
22	func pmColumn(pm *PathModel, cell func(pathStep) string) []string {
23		var out []string
24		for _, s := range pm.table.Items() {
25			out = append(out, cell(s))
26		}
27		return out
28	}
29	
30	func pmSteps(pm *PathModel) []string    { return pmColumn(pm, pathStep.stepCell) }
31	func pmAddrs(pm *PathModel) []string    { return pmColumn(pm, pathStep.addressCell) }
32	func pmHopCells(pm *PathModel) []string { return pmColumn(pm, pathStep.hopCell) }
33	func pmRTTCells(pm *PathModel) []string { return pmColumn(pm, pathStep.rttCell) }
34	
35	func lanRoute() netcheck.RouteHop { return defaultRouteHop() }
36	
37	// resolvedWith launches 1.1.1.1 and delivers the resolved message of the run.
38	func resolvedWith(t *testing.T, route netcheck.RouteHop, routeErr error) *PathModel {
39		t.Helper()
40		pm, _ := newPM(t)
41		pm, _ = launched(t, pm, "1.1.1.1")
42		pm, _ = pmFeed(t, pm, pathResolvedMsg{
43			gen: pm.gen, addr: netip.MustParseAddr("1.1.1.1"), route: route, routeErr: routeErr,
44		})
45		return pm
46	}
47	
48	func targetHop(ttl int) nettrace.Hop {
49		return nettrace.Hop{TTL: ttl, Kind: nettrace.HopTarget, Addr: netip.MustParseAddr("1.1.1.1")}
50	}
51	
52	// Criterion 1: source, interface, gateway, then the hops.
53	func TestPathColumnStartsWithTheLocalSteps(t *testing.T) {
54		pm := resolvedWith(t, lanRoute(), nil)
55		pm, _ = pmFeed(t, pm,
56			pathHopMsg{gen: pm.gen, hop: hopOf(2, nettrace.HopRouter)},
57			pathHopMsg{gen: pm.gen, hop: hopOf(1, nettrace.HopRouter)},
58		)
59		pm, _ = pmFeed(t, pm, pathDoneMsg{gen: pm.gen, result: nettrace.Result{
60			Outcome: nettrace.OutcomeReached,
61			Hops:    []nettrace.Hop{hopOf(1, nettrace.HopRouter), targetHop(2)},
62		}})
63	
64		if got, want := pmSteps(pm), []string{"source", "interface", "gateway", "router", "target"}; !reflect.DeepEqual(got, want) {
65			t.Errorf("Step column = %v, want %v", got, want)
66		}
67		addrs := pmAddrs(pm)
68		if len(addrs) < 3 {
69			t.Fatalf("Address column = %v, want at least the three local rows", addrs)
70		}
71		if got, want := addrs[:3], []string{"this machine", "eth0 (192.168.1.21)", "192.168.1.1"}; !reflect.DeepEqual(got, want) {
72			t.Errorf("Address of the local rows = %v, want %v", got, want)
73		}
74	}
75	
76	// The local rows asked nobody: Hop and RTT are empty, not "-".
77	func TestPathLocalRowsHaveNoHopAndNoRTT(t *testing.T) {
78		pm := resolvedWith(t, lanRoute(), nil)
79		pm, _ = pmFeed(t, pm, pathHopMsg{gen: pm.gen, hop: hopOf(1, nettrace.HopRouter)})
80	
