21	
22	// onPathTab returns a laid-out model standing on the Path tab, with a fake
23	// engine so that enter never touches a socket or a resolver.
24	func onPathTab(t *testing.T) *Model {
25		t.Helper()
26		m := newTestModel(t)
27		if m.pathModel == nil {
28			t.Fatal("New() built no pathModel")
29		}
30		m.pathModel.engine = (&fakeEngine{}).engine()
31		return feed(t, m, testutil.Keys("tab", "tab", "tab", "tab")...)
32	}
