34	// tracing returns a model on the Path tab with a trace launched over host.
35	func tracing(t *testing.T, host string) *Model {
36		t.Helper()
37		m := onPathTab(t)
38		m = feed(t, m, testutil.Type(host)...)
39		return feed(t, m, testutil.Key("enter"))
40	}
