42	func TestPathIsTheFifthTab(t *testing.T) {
43		if tabPath != 4 {
44			t.Errorf("tabPath = %d, want 4 (the fifth tab, after Forward)", tabPath)
45		}
46		if tabCount != 5 {
47			t.Errorf("tabCount = %d, want 5", tabCount)
48		}
49	}
