51	func TestPathIsReachedByTabAloneAndCyclesBothWays(t *testing.T) {
52		m := newTestModel(t)
53		for _, want := range []int{tabPorts, tabInterfaces, tabForward, tabPath, tabDiagnostics} {
54			m = feed(t, m, testutil.Key("tab"))
55			if m.activeTab != want {
56				t.Fatalf("tab: activeTab = %d, want %d", m.activeTab, want)
57			}
58		}
59		for _, want := range []int{tabPath, tabForward, tabInterfaces, tabPorts, tabDiagnostics} {
60			m = feed(t, m, testutil.Key("shift+tab"))
61			if m.activeTab != want {
62				t.Fatalf("shift+tab: activeTab = %d, want %d", m.activeTab, want)
63			}
64		}
