38	func resolvedWith(t *testing.T, route netcheck.RouteHop, routeErr error) *PathModel {
39		t.Helper()
40		pm, _ := newPM(t)
41		pm, _ = launched(t, pm, "1.1.1.1")
42		pm, _ = pmFeed(t, pm, pathResolvedMsg{
