69			t.Fatalf("Address column = %v, want at least the three local rows", addrs)
70		}
71		if got, want := addrs[:3], []string{"this machine", "eth0 (192.168.1.21)", "192.168.1.1"}; !reflect.DeepEqual(got, want) {
72			t.Errorf("Address of the local rows = %v, want %v", got, want)
